+<?php
+/**
+ * Login Page with Login Attempts Tracking & Audit Trail
+ */
+
+// Load configuration
+require_once __DIR__ . '/config.php';
+require_once CONFIG_PATH . '/database.php';
+require_once INCLUDE_PATH . '/functions.php';
+require_once INCLUDE_PATH . '/auth.php';
+
+// Redirect if already logged in
+if (isset($_SESSION['user_id'])) {
+    $user = getCurrentUser();
+    if ($user) {
+        switch ($user['role']) {
+            case 'super_admin':
+                header('Location: ' . SITE_URL . '/superadmin/dashboard.php');
+                break;
+            case 'admin':
+                header('Location: ' . SITE_URL . '/admin/dashboard.php');
+                break;
+            case 'supply':
+                header('Location: ' . SITE_URL . '/supply/dashboard.php');
+                break;
+            default:
+                header('Location: ' . SITE_URL . '/user/dashboard.php');
+        }
+        exit();
+    }
+}
+
+$error = '';
+$show_captcha = false;
+
+// Max login attempts before lockout
+define('MAX_LOGIN_ATTEMPTS', 5);
+define('LOCKOUT_TIME_MINUTES', 15);
+
+if ($_SERVER['REQUEST_METHOD'] == 'POST') {
+    // Use prepared statement to prevent SQL injection
+    $username = trim($_POST['username']);
+    $password = $_POST['password'];
+    $remember = isset($_POST['remember']) ? true : false;
+    
+    // Use prepared statement instead of direct query
+    $stmt = $conn->prepare("SELECT * FROM users WHERE username = ? OR email = ?");
+    $stmt->bind_param("ss", $username, $username);
+    $stmt->execute();
+    $result = $stmt->get_result();
+    
+    if ($result && $row = $result->fetch_assoc()) {
+        
+        // Check if account is locked
+        $is_locked = false;
+        $lock_message = '';
+        
+        if ($row['locked_until'] && strtotime($row['locked_until']) > time()) {
+            $is_locked = true;
+            $remaining_minutes = ceil((strtotime($row['locked_until']) - time()) / 60);
+            $lock_message = "⏰ Account is locked. Please try again after {$remaining_minutes} minutes.";
+        }
+        
+        // Check if too many attempts (even if not locked yet)
+        $attempts = (int)($row['login_attempts'] ?? 0);
+        if ($attempts >= MAX_LOGIN_ATTEMPTS && !$is_locked) {
+            // Lock the account
+            $lock_until = date('Y-m-d H:i:s', strtotime('+' . LOCKOUT_TIME_MINUTES . ' minutes'));
+            $update_lock = $conn->prepare("UPDATE users SET locked_until = ? WHERE id = ?");
+            $update_lock->bind_param("si", $lock_until, $row['id']);
+            $update_lock->execute();
+            $update_lock->close();
+            
+            $is_locked = true;
+            $lock_message = "⏰ Too many failed attempts. Account locked for " . LOCKOUT_TIME_MINUTES . " minutes.";
+            
+            // Log account lock to audit trail
+            if (function_exists('logAccountLocked')) {
+                logAccountLocked($row['id'], $attempts);
+            }
+        }
+        
+        if ($is_locked) {
+            $error = $lock_message;
+            // Log failed attempt on locked account
+            if (function_exists('logLogin')) {
+                logLogin($row['id'], false, $username);
+            }
+        }
+        elseif ($row['status'] == 'pending') {
+            $error = '⏳ Your account is pending approval from an administrator. You will receive an email once approved.';
+            // Reset login attempts on pending account (they can try after approval)
+            $reset_attempts = $conn->prepare("UPDATE users SET login_attempts = 0 WHERE id = ?");
+            $reset_attempts->bind_param("i", $row['id']);
+            $reset_attempts->execute();
+            $reset_attempts->close();
+            
+            // Log pending account attempt
+            if (function_exists('logLogin')) {
+                logLogin($row['id'], false, $username);
+            }
+        } 
+        elseif ($row['status'] == 'inactive') {
+            $error = '⚠️ Your account has been deactivated. Please contact the administrator.';
+            // Log inactive account attempt
+            if (function_exists('logLogin')) {
+                logLogin($row['id'], false, $username);
+            }
+        } 
+        elseif (password_verify($password, $row['password'])) {
+            // Successful login - Reset login attempts
+            $reset_stmt = $conn->prepare("UPDATE users SET login_attempts = 0, locked_until = NULL, last_login = NOW() WHERE id = ?");
+            $reset_stmt->bind_param("i", $row['id']);
+            $reset_stmt->execute();
+            $reset_stmt->close();
+            
+            // Set session variables
+            $_SESSION['user_id'] = $row['id'];
+            $_SESSION['role'] = $row['role'];
+            $_SESSION['username'] = $row['username'];
+            $_SESSION['user_name'] = $row['firstname'] . ' ' . $row['lastname'];
+            $_SESSION['user_email'] = $row['email'];
+            
+            // Log successful login to audit trail
+            if (function_exists('logLogin')) {
+                logLogin($row['id'], true);
+            }
+            
+            // Also log to old functions for compatibility
+            if (function_exists('logAudit')) {
+                logAudit('LOGIN', 'users', $row['id'], null, 'Login successful');
+            }
+            if (function_exists('logActivity')) {
+                logActivity('Login', $row['id'], "User logged in successfully: {$row['username']}");
+            }
+            
+            // Redirect based on role
+            switch ($row['role']) {
+                case 'super_admin':
+                    header('Location: ' . SITE_URL . '/superadmin/dashboard.php');
+                    break;
+                case 'admin':
+                    header('Location: ' . SITE_URL . '/admin/dashboard.php');
+                    break;
+                case 'supply':
+                    header('Location: ' . SITE_URL . '/supply/dashboard.php');
+                    break;
+                default:
+                    header('Location: ' . SITE_URL . '/user/dashboard.php');
+            }
+            exit();
+        } else {
+            // Failed login - Increment attempts
+            $new_attempts = $attempts + 1;
+            $remaining_attempts = MAX_LOGIN_ATTEMPTS - $new_attempts;
+            
+            $update_attempts = $conn->prepare("UPDATE users SET login_attempts = ? WHERE id = ?");
+            $update_attempts->bind_param("ii", $new_attempts, $row['id']);
+            $update_attempts->execute();
+            $update_attempts->close();
+            
+            // Check if this failed attempt will trigger a lock on next attempt
+            if ($remaining_attempts > 0) {
+                $error = "❌ Invalid password. You have {$remaining_attempts} attempt(s) remaining before account lockout.";
+            } else {
+                $error = "❌ Invalid password. Account will be locked after next failed attempt.";
+            }
+            
+            // Log failed login to audit trail
+            if (function_exists('logLogin')) {
+                logLogin($row['id'], false, $username);
+            }
+            
+            // Also log to old functions for compatibility
+            if (function_exists('logActivity')) {
+                logActivity('Failed Login', $row['id'], "Failed login attempt for username: $username. Attempt {$new_attempts} of " . MAX_LOGIN_ATTEMPTS);
+            }
+            
+            // Show captcha after 3 attempts
+            if ($new_attempts >= 3) {
+                $show_captcha = true;
+            }
+        }
+    } else {
+        // User not found - log to audit trail (no user_id)
+        if (function_exists('logLogin')) {
+            // Pass null user_id for non-existent user
+            global $conn;
+            $log_stmt = $conn->prepare("
+                INSERT INTO audit_trail (user_id, action, action_category, description, ip_address, user_agent, created_at) 
+                VALUES (NULL, 'FAILED_LOGIN', 'SECURITY', ?, ?, ?, NOW())
+            ");
+            $description = "Failed login attempt - username/email not found: $username";
+            $ip = getUserIP();
+            $ua = $_SERVER['HTTP_USER_AGENT'] ?? null;
+            $log_stmt->bind_param("sss", $description, $ip, $ua);
+            $log_stmt->execute();
+            $log_stmt->close();
+        }
+        
+        if (function_exists('logActivity')) {
+            logActivity('Failed Login', 0, "Failed login attempt - username/email not found: $username");
+        }
+        
+        $error = '❌ Username or email not found. Please check your credentials.';
+    }
+    $stmt->close();
+}
